CREATE TABLE t1_a(a INTEGER PRIMARY KEY, b TEXT); INSERT INTO t1_a VALUES(123, 't1_a'); CREATE TABLE t1_b(c INTEGER PRIMARY KEY, d TEXT); CREATE VIEW t1 AS SELECT a, b FROM t1_a UNION ALL SELECT c, d FROM t1_b; CREATE TABLE t3_a(k INTEGER PRIMARY KEY, v TEXT); INSERT INTO t3_a VALUES(456, 't3_a'); CREATE TABLE t3_b(k INTEGER PRIMARY KEY, v TEXT); CREATE VIEW t3 AS SELECT * FROM t3_a UNION ALL SELECT * FROM t3_b;